-- Celtic myths linked to places (24 entries)
-- Generated 2026-11-16. Portable SQL: works in SQLite, PostgreSQL and MySQL (utf8mb4).
-- latitude/longitude = main map pin (approximate; verify before publishing).

DROP TABLE IF EXISTS myths;

CREATE TABLE myths (
    id          INTEGER      PRIMARY KEY,
    myth_name   VARCHAR(150) NOT NULL,
    region_name VARCHAR(50)  NOT NULL,
    location    VARCHAR(300) NOT NULL,
    latitude    DECIMAL(8,5) NOT NULL,
    longitude   DECIMAL(8,5) NOT NULL,
    place_name  VARCHAR(150) NOT NULL,
    myth_text   TEXT         NOT NULL,
    source      VARCHAR(300) NOT NULL
);

