INSERT INTO myths (id, myth_name, region_name, location, latitude, longitude, place_name, myth_text, source) VALUES
(1, 'The Children of Lir', 'Ireland', 'Lough Derravaragh; then the Sea of Moyle (North Channel); then Inishglora island, Co. Mayo', 53.65000, -7.37000, 'Castlepollard, Co. Westmeath', 'Lir, a lord of the Tuatha Dé Danann, marries Aoife after his first wife dies. Jealous of his love for his four children (Fionnuala, Aodh, Fiachra and Conn), Aoife turns them into swans on the shore of Lough Derravaragh. They keep their human voices and must spend 300 years on that lake, 300 years on the stormy Sea of Moyle, and 300 years off Inishglora. The spell ends when they hear a Christian bell. They turn back into human form, now very old, are baptised and die. They are buried together.', 'Oidheadh Chlainne Lir (one of the Three Sorrows of Storytelling)'),
(2, 'The Cattle Raid of Cooley (Táin Bó Cúailnge)', 'Ireland', 'Cooley Peninsula; Rathcroghan (Cruachan), Co. Roscommon; Ardee (Áth Fhirdiad), Co. Louth', 54.02000, -6.20000, 'Carlingford, Co. Louth', 'In bed at Cruachan, Queen Medb of Connacht and her husband Ailill compare their wealth. They are equal except for one thing: Ailill owns the great white-horned bull. Medb raises an army to take the only equal bull, the Brown Bull of Cooley in Ulster. The Ulstermen are struck down by a curse of weakness, so the teenage Cú Chulainn holds the fords alone, fighting one champion a day. At Ardee he has to kill his foster-brother Ferdiad after three days of combat. In the end the two bulls fight across Ireland. The Brown Bull kills the White, scatters its body over the land, and dies of exhaustion.', 'Táin Bó Cúailnge, Ulster Cycle (Book of the Dun Cow, Book of Leinster)'),
(3, 'The Salmon of Knowledge', 'Ireland', 'River Boyne at Linn Féic', 53.70000, -6.54000, 'Slane, Co. Meath', 'The salmon ate nine hazelnuts that fell into a sacred well, and whoever eats it first will know everything. The poet Finnegas spends seven years fishing for it in a pool on the Boyne. When he finally catches it, he tells his young pupil Fionn to cook it but not to eat any. Fionn burns his thumb on the skin and sucks it to ease the pain. All the knowledge passes to him. From then on, Fionn only has to put his thumb in his mouth to know what he needs.', 'Macgnímartha Finn (The Boyhood Deeds of Fionn), Fenian Cycle'),
(4, 'The Pursuit of Diarmuid and Gráinne', 'Ireland', 'Ben Bulben (Diarmuid''s death); Hill of Tara, Co. Meath (start of the flight)', 54.37000, -8.47000, 'Drumcliff, Co. Sligo', 'Gráinne, daughter of the High King, is promised to the ageing Fionn. At the betrothal feast at Tara she puts a magical obligation (geis) on the young warrior Diarmuid to run away with her. They flee across Ireland for years, sleeping in a different place each night, which is why so many dolmens bear their name. Fionn eventually makes peace, then invites Diarmuid to hunt the boar of Ben Bulben, the only creature fated to kill him. The boar wounds him mortally. Water from Fionn''s hands could heal him, but Fionn lets it slip through his fingers twice, and by the third time Diarmuid is dead.', 'Tóraíocht Dhiarmada agus Ghráinne, Fenian Cycle'),
(5, 'The Dream of Aengus', 'Ireland', 'Brú na Bóinne (Newgrange); Caer''s lake (Loch Bél Dracon) has no agreed location', 53.69000, -6.48000, 'Donore, Co. Meath', 'Aengus dreams night after night of a beautiful girl and falls sick with longing. After a year of searching he finds her: Caer, one of 150 maidens chained in pairs at a lake. Every other year at Samhain she becomes a swan. Aengus is told he may marry her if he can recognise her in swan form. He picks her out, turns into a swan himself, and the two fly three times around the lake. They return to Brú na Bóinne singing a song so sweet that everyone who hears it sleeps for three days and three nights.', 'Aislinge Óenguso, Mythological Cycle'),
(6, 'Oisín in Tír na nÓg', 'Ireland', 'Glenasmole (Gleann na Smól), Dublin Mountains', 53.24000, -6.36000, 'Bohernabreena, Co. Dublin', 'Niamh of the Golden Hair rides out of the sea on a white horse and invites Oisín, son of Fionn, to Tír na nÓg, the Land of Youth. He lives there happily for what feels like three years. Homesick, he borrows the horse to visit Ireland, with a warning never to touch the ground. He finds that 300 years have passed and the Fianna are gone. At Glenasmole he leans down to help men lift a stone, the saddle-girth breaks and he falls. He instantly becomes an old man. Before he dies he tells the old stories to Saint Patrick.', 'Laoi Oisín i dTír na nÓg (18th-century poem, older tradition)'),
(7, 'The Giant''s Causeway and Fingal''s Cave', 'Ireland / Scotland', 'Giant''s Causeway, Co. Antrim; Fingal''s Cave, isle of Staffa, Inner Hebrides', 55.24000, -6.51000, 'Bushmills, Co. Antrim', 'Fionn is challenged by the Scottish giant Benandonner and builds a stone causeway across the sea so they can fight. When he sees how huge Benandonner is, he runs home. His wife Oonagh dresses him as a baby and puts him in a cradle. Benandonner arrives, sees the size of the "baby", imagines how big the father must be, and flees back to Scotland. He tears up the causeway behind him. Only its two ends remain: the basalt columns at Antrim and at Fingal''s Cave on Staffa.', 'Later oral folklore (not in the medieval manuscripts)'),
(8, 'The Dullahan and the headless coach', 'Ireland', 'Blackwater valley, North Cork: Castle Hyde and the glen beyond Ballyhooly; Doneraile; Killavullen', 52.15000, -8.31000, 'Fermoy, Co. Cork', 'The Dullahan is a death omen. He rides a black horse at night and holds his own head under his arm or in his hand. Sometimes he drives a black coach pulled by headless horses. Wherever he stops, someone in that house dies. Croker collected several tales around North Cork. A headless coach was said to drive back and forth between Castle Hyde and a glen past Ballyhooly. At Doneraile it stopped at houses in turn, and whoever opened the door had a basin of blood thrown in their face. In "Hanlon''s Mill", Mick Noonan walks home at night and sees a black coach pulled by six headless black horses. The next morning he learns that Master Wrixon of Ballygibblin has died.', 'Thomas Crofton Croker, Fairy Legends and Traditions of the South of Ireland (1825-28), section "The Dullahan"'),
(9, 'Aoibheall, the banshee of Craglea', 'Ireland', 'Craglea (Craig Liath) above Lough Derg, with the well Tobereevul; Clontarf, Dublin (battle of 1014)', 52.83000, -8.46000, 'Killaloe, Co. Clare', 'A banshee is a fairy woman who keens (wails) before a death in certain old Irish families. Some have names, and the most famous is Aoibheall, who lived on the rock of Craglea above Killaloe. She protected the Dál gCais, Brian Boru''s people, whose royal seat was nearby. The night before the battle of Clontarf in 1014, she appeared to the old High King. She told him he would die the next day and which of his sons would rule after him. In some versions she is seen washing the soldiers'' bloodstained clothes. She also loved Brian''s companion Dúnlang O''Hartigan and begged him not to fight; he went anyway and was killed. Brian''s army won, but Brian was killed in his tent. Local folklore says Aoibheall left Craglea when its woods were cut down.', 'Cogadh Gáedel re Gallaib (12th-century account of Clontarf) and later Clare folklore'),
(10, 'The changeling of Ballyvadlea', 'Ireland', 'Ballyvadlea townland and the Kylenagranagh fairy fort', 52.48000, -7.56000, 'Cloneen / Mullinahone, Co. Tipperary', 'In Irish belief, the fairies steal babies, young mothers or new brides and leave a changeling in their place: a sickly, bad-tempered fairy that looks like the person. People tried to drive it out with iron, herbs or fire so the real person would come back. In March 1895 this belief led to a real killing. Bridget Cleary, a young dressmaker from Ballyvadlea, fell ill with bronchitis. Her husband Michael became convinced that the fairies had taken her at the Kylenagranagh fort and left a changeling. With relatives'' help he forced herbal remedies on her, then killed her and burned her body, saying he had only destroyed the changeling. He then waited at the fairy fort for his "real" wife to ride out. He was convicted of manslaughter. A children''s rhyme still asks whether she was a witch, a fairy or Michael Cleary''s wife.', 'Real case, 1895 (newspaper reports and trial); Angela Bourke, The Burning of Bridget Cleary (1999)'),
(11, 'The Cailleach and the Corryvreckan whirlpool', 'Scotland', 'Gulf of Corryvreckan between Jura and Scarba; Ben Cruachan and Loch Awe', 56.15000, -5.72000, 'Isle of Jura, Argyll', 'The Cailleach brings winter. At the end of autumn she washes her enormous plaid in the Corryvreckan whirlpool. For three days the roar of the water can be heard far away. When she lifts the plaid out it is pure white, and she lays it over the land as the first snow. Another tale says she guarded a spring on top of Ben Cruachan and had to cover it every evening. One night she fell asleep, the spring overflowed, and the water flooded the glen to make Loch Awe.', 'Highland and Hebridean oral tradition (collected 19th-20th centuries)'),
(12, 'The Blue Men of the Minch', 'Scotland', 'Sound of Shiant (Stream of the Blue Men), between the Shiant Isles and Lewis', 57.89000, -6.38000, 'Shiant Isles, Outer Hebrides', 'The Blue Men live in underwater caves in the strait and stir up storms to sink passing ships. When a boat approaches, their chief rises from the waves and shouts two lines of verse at the captain. If the captain can answer at once with two rhyming lines to finish the verse, the Blue Men respect him and let the ship pass. If he fails, they try to capsize the boat. Sailors said the Blue Men sleep when the sea is calm.', 'Hebridean folklore, recorded by Donald Mackenzie, Scottish Folk-Lore and Folk Life (1935)'),
(13, 'Saint Columba and the beast of the River Ness', 'Scotland', 'River Ness, flowing out of Loch Ness', 57.47000, -4.23000, 'Inverness', 'When Columba travels to meet the Pictish king, he finds locals burying a man who was killed by a beast in the river. Columba asks one of his companions to swim across to fetch a boat. The beast rises and rushes at the swimmer with its mouth wide open. Columba raises his hand, makes the sign of the cross, and orders it to go back. The beast flees as if pulled by ropes. This is the oldest written mention of a creature in the Loch Ness area.', 'Adomnán, Life of Columba (Vita Columbae), around 700'),
(14, 'Tam Lin', 'Scotland', 'Carterhaugh, where the Ettrick and Yarrow waters meet', 55.53000, -2.88000, 'Selkirk, Scottish Borders', 'Young women are warned not to go to Carterhaugh, which belongs to Tam Lin. Janet goes anyway, picks a rose, and Tam Lin appears. She becomes pregnant. He tells her he is a human taken by the Fairy Queen and that he will soon be paid as a tithe to hell. To save him, Janet waits at a crossroads on Halloween night. She pulls him from his white horse as the fairy procession rides past. The fairies turn him into a snake, a bear, a lion and a red-hot iron, but she holds on. When he becomes a burning coal she throws him into a well, and he comes out a naked man. She covers him with her green cloak and wins him back.', 'Traditional Border ballad (Child Ballad 39)'),
(15, 'The Red and White Dragons of Dinas Emrys', 'Wales', 'Dinas Emrys hill fort, Snowdonia (Eryri)', 53.02000, -4.08000, 'Beddgelert, Gwynedd', 'In Lludd and Llefelys, two fighting dragons are caught, made drunk on mead and buried in a stone chest at this spot. Centuries later, King Vortigern tries to build a fortress there, but the walls fall down every night. His advisers tell him to sprinkle the ground with the blood of a boy with no father. The boy they find, Emrys, reveals that a pool under the hill hides two sleeping dragons. When the pool is drained, the dragons wake and fight. The white dragon wins at first, but the red dragon drives it out. Emrys explains that the Britons will one day drive out the Saxons. The red dragon is now on the Welsh flag.', 'Historia Brittonum (9th century); Lludd and Llefelys (Mabinogion); Geoffrey of Monmouth (12th century)'),
(16, 'The Lady of Llyn y Fan Fach', 'Wales', 'Llyn y Fan Fach, under the Black Mountain (Y Mynydd Du)', 51.88000, -3.74000, 'Myddfai, Carmarthenshire', 'A young farmer sees a beautiful woman sitting on the surface of the lake. He offers her bread to win her. She refuses the hard-baked bread and the raw dough, but accepts the lightly baked bread on the third day. She agrees to marry him on one condition: if he strikes her three times without a reason, she will leave. She brings herds of fairy cattle and they have three sons. Over the years he taps her three times for small reasons, like her crying at a wedding and laughing at a funeral. After the third blow she walks back into the lake, calling all her cattle after her, even the oxen pulling a plough. Her sons become the famous Physicians of Myddfai, healers taught by their mother.', 'Local oral tradition, written down in the 19th century'),
(17, 'Blodeuwedd, the woman made of flowers', 'Wales', 'Tomen y Mur (Mur Castell); Llyn Morwynion; the Cynfal river (Llech Ronw); Nantlle valley', 52.93000, -3.93000, 'Trawsfynydd / Ffestiniog, Gwynedd', 'Lleu''s mother has cursed him never to have a human wife. The magicians Math and Gwydion create one from the flowers of oak, broom and meadowsweet, and name her Blodeuwedd ("flower face"). She falls in love with the hunter Gronw Pebr, and they plot to kill Lleu. Lleu can only be killed in an impossible position, with a spear forged over a year. Blodeuwedd tricks him into showing it. Gronw strikes, and Lleu flies off as a wounded eagle. Gwydion finds him in an oak tree in the Nantlle valley and heals him. Blodeuwedd''s maidens drown in Llyn Morwynion as they flee. Gwydion turns her into an owl, a bird shunned by all others. Lleu kills Gronw with a spear that goes through the stone he hides behind, the Llech Ronw.', 'Math fab Mathonwy, Fourth Branch of the Mabinogi'),
(18, 'Manannan mac Lir, the island''s first king', 'Isle of Man', 'South Barrule (his fort); Tynwald Hill (Midsummer rush offering)', 54.15000, -4.67000, 'St John''s, Isle of Man', 'Manannan is the sea god and the first ruler of the Isle of Man, which was named after him. To protect the island from invaders, he wraps it in a mist so enemies sail past without seeing it. It is said he could also make one warrior look like a hundred to scare off attackers. As rent, the Manx people had to bring him bundles of green rushes on Midsummer Eve. Today, bundles of rushes are still laid at Tynwald Hill in his honour during the Midsummer ceremony.', 'Manx oral tradition and the 16th-century Manannan Ballad'),
(19, 'The Moddey Dhoo of Peel Castle', 'Isle of Man', 'Peel Castle, St Patrick''s Isle', 54.23000, -4.70000, 'Peel', 'The soldiers guarding Peel Castle often saw a large black dog that came into the guard-room at night and lay by the fire. They became used to it, but nobody ever dared to be alone with it. Each night two soldiers carried the keys together through a passage to the captain. One night a drunk soldier mocked the others and went alone. Terrible noises were heard. He came back speechless and terrified, and died three days later without saying what he had seen. The dog was never seen again, and the passage was walled up.', 'George Waldron, A Description of the Isle of Man (1726)'),
(20, 'The drowned city of Ys', 'Brittany', 'Bay of Douarnenez; Quimper Cathedral (statue of King Gradlon)', 48.12000, -4.40000, 'Douarnenez, Finistère', 'King Gradlon builds Ys, the most beautiful city in the world, for his daughter Dahut. It lies below sea level, protected by a dike with a bronze gate, and only the king holds the key. Dahut lives a wild life and takes a new lover every night. One night a stranger (the devil, in many versions) persuades her to steal the key from her sleeping father and open the gate. The sea floods Ys. Gradlon escapes on his horse Morvarc''h with Dahut behind him, but the waves keep rising. Saint Gwénolé tells him to throw off the sinner. Dahut falls into the sea and becomes a mermaid. Gradlon settles in Quimper. Fishermen say the bells of Ys can still be heard under the water on calm days.', 'Breton legend, written down from the 15th century; Barzaz Breiz (1839)'),
(21, 'Merlin and Viviane in the forest of Brocéliande', 'Brittany', 'Forest of Paimpont: Fontaine de Barenton; Val sans Retour; Tombeau de Merlin', 48.03000, -2.24000, 'Paimpont, Ille-et-Vilaine', 'If you pour water from the Fontaine de Barenton onto its stone slab, a violent storm breaks out; in Yvain the knight does this to challenge the fountain''s guardian. Merlin meets the young Viviane in this forest and falls in love with her. He teaches her his magic, and she uses one of his own spells to trap him forever in an invisible tower of air (or under a stone). In the nearby Val sans Retour, Morgan le Fay, betrayed by her lover, cast a spell that traps any unfaithful knight who enters. The spell is finally broken by Lancelot, who is entirely faithful to Queen Guinevere.', 'Wace, Roman de Rou (c. 1160); Chrétien de Troyes, Yvain; Vulgate (Lancelot-Grail) cycle (13th century)'),
(22, 'The Mermaid of Zennor', 'Cornwall', 'Church of St Senara (Mermaid Chair); Pendour Cove', 50.19000, -5.57000, 'Zennor, West Penwith', 'For years a beautiful, richly dressed woman comes to services at Zennor church, and nobody knows where she comes from. She falls in love with the voice of Mathey Trewella, the best singer in the parish. One Sunday he follows her out of the church and they are never seen again. Long after, a mermaid asks a ship anchored at Pendour Cove to move its anchor because it is blocking the door of her home, where her husband and children are waiting. The villagers understand that Mathey is now living under the sea. On summer evenings people say you can hear him singing from the cove. The carved "Mermaid Chair" in the church is said to remember her.', 'Cornish folklore, written down by William Bottrell (1873)'),
(23, 'Breogán''s Tower and the sight of Ireland', 'Galicia & Asturias', 'Tower of Hercules (identified with Breogán''s tower at Brigantia)', 43.39000, -8.41000, 'A Coruña, Galicia', 'Breogán, a king of the Gaels in Iberia, founds the city of Brigantia and builds a great tower there. From the top of the tower on a clear winter evening, his son Íth sees a distant green land: Ireland. Íth sails there, but the Tuatha Dé Danann who rule Ireland kill him. To avenge him, Breogán''s grandsons, the sons of Míl, sail from Galicia and conquer Ireland. Their descendants are, in the legend, the Gaels, the ancestors of the Irish.', 'Lebor Gabála Érenn (The Book of the Taking of Ireland, 11th century)'),
(24, 'The xana of the Cioyo waterfall', 'Galicia & Asturias', 'Cascada del Cioyo, in the woods of western Asturias', 43.50000, -7.00000, 'Castropol, Asturias', 'Xanas are fairies of springs and rivers. They sing on summer nights, especially on Saint John''s Eve, and are said to guard treasure. A xana living in the Cioyo woods fell in love with a young man who came every day to nap beside the river, lulled by the current. One afternoon a sudden storm swept him downstream towards the waterfall. The xana, who always watched over him, used her magic to stop him going over the drop. She created a deep pool at the foot of the fall to catch him. Hikers swim in that pool today at the end of the waterfall walk.', 'Asturian oral tradition (as told by Turismo Asturias)');
